contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(uint128 price) public {
        // deployer (this contract) is a ward initially
        bool revertedWhenWard;
        try c.updatePrice(price) { revertedWhenWard = false; } catch { revertedWhenWard = true; }
        // revoke authorization, call must revert and not change state
        c.deny(address(this));
        bool revertedWhenDenied;
        try c.updatePrice(price + 1) { revertedWhenDenied = false; } catch { revertedWhenDenied = true; }
        uint128 deniedPrice = c.latestPrice();
        // re-authorize, call must succeed and apply the price
        c.rely(address(this));
        c.updatePrice(price + 2);
        assert(!revertedWhenWard && revertedWhenDenied && deniedPrice == price && c.latestPrice() == price + 2);
    }
    receive() external payable {}
}

