contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint128 price) public {
        bool isWard = (c.wards(address(this)) == 1);
        uint128 beforePrice = c.latestPrice();
        uint256 beforeUpdate = c.lastPriceUpdate();

        bool reverted;
        try c.updatePrice(price) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            assert(
                isWard
                && c.latestPrice() == price
                && c.lastPriceUpdate() == block.timestamp
            );
        } else {
            assert(
                !isWard
                && c.latestPrice() == beforePrice
                && c.lastPriceUpdate() == beforeUpdate
            );
        }
    }

    receive() external payable {}
}

